import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    n = int(sys.stdin.readline().strip())
    graph = defaultdict(list)
    edges = []

    for _ in range(n - 1):
        u, v, x, c = read_ints()
        graph[u].append((v, x, c))
        graph[v].append((u, x, c))
        edges.append((u, v, x, c))

    # Precompute the shortest paths using BFS
    def bfs(start):
        dist = [-1] * (n + 1)
        queue = deque([(start, 0)])
        dist[start] = 0
        paths = defaultdict(lambda: [0, 0])

        while queue:
            node, d = queue.popleft()
            for neighbor, x, c in graph[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = d + 1
                    queue.append((neighbor, d + 1))
                    paths[neighbor] = [paths[node][0] + (1 if c == 0 else 0), paths[node][1] + (1 if c == 1 else 0)]

        return paths

    # Compute the jelliness
    jelliness = 1
    for u in range(1, n + 1):
        paths = bfs(u)
        for v in range(u + 1, n + 1):
            red_count = paths[v][0]
            black_count = paths[v][1]
            if abs(red_count - black_count) <= 2:
                product = 1
                for edge in edges:
                    if (edge[0] == u and edge[1] == v) or (edge[1] == u and edge[0] == v):
                        product *= edge[2]
                        product %= MOD
                jelliness *= product
                jelliness %= MOD

    print(jelliness)

if __name__ == "__main__":
    main()
